  ('83b26498-a39b-5615-a089-48e2bd727707', null, (select id from public.skills where slug = 'read-g9-comparing-texts'), null, 'medium',
   $q$What do the "miles beneath the seniors' names" in the last stanza represent, based on Text 1?$q$, $q$[{"text":"The hidden roots that kept the oaks standing through the autumn gales.","is_correct":true},{"text":"The snow that bent the pine's crown nearly to the ground.","is_correct":false,"misconception_token":"wrong-detail"},{"text":"The loose top layer of earth that held the pine's thin roots.","is_correct":false,"misconception_token":"wrong-detail"},{"text":"The great height that the pine reached in a single summer.","is_correct":false,"misconception_token":"reverses-meaning"}]$q$::jsonb, $q$The hidden roots that kept the oaks standing through the autumn gales.$q$, $q$The poem calls the miles "the roots that never showed at the start," linking unseen training to the oaks' deep roots. The pine's height is the showy quality the poem contrasts with the miles.$q$, 'draft', 'cce15e04-4a2f-5fc0-9fc3-dd9a766dd461')
