  ('6fe10bb0-1a89-5845-b813-da80dd099744', null, (select id from public.skills where slug = 'read-g9-comparing-texts'), null, 'hard',
   $q$Text 1 ends with the pine bent over, but Text 2 ends with the coach showing a chart. What effect does this change have?$q$, $q$[{"text":"It makes the lesson about speed, since the chart shows the speaker should start even faster.","is_correct":false,"misconception_token":"reverses-meaning"},{"text":"It makes the failure a starting point for improvement, since the chart shows what the speaker can do next.","is_correct":true},{"text":"It makes the lesson about cheating, since the chart proves the seniors broke the race rules.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"It makes the ending more hopeless, since the speaker is told the seniors will always be faster.","is_correct":false,"misconception_token":"misreads-tone"}]$q$::jsonb, $q$It makes the failure a starting point for improvement, since the chart shows what the speaker can do next.$q$, $q$The coach points to the training miles, a practical model the speaker can follow, so the poem looks forward. Nothing says the seniors will always be faster, so the hopeless reading is unsupported.$q$, 'draft', 'cce15e04-4a2f-5fc0-9fc3-dd9a766dd461')
