  ('09d5d448-a6dd-57ba-8cd7-07b086a4a319', null, (select id from public.skills where slug = 'read-g9-figurative-language'), null, 'easy',
   $q$Coach Delgado called the first set "a learning experience." What did he most likely mean?$q$, $q$[{"text":"The team had played poorly, and he was saying so gently.","is_correct":true},{"text":"The team had learned the other team's plays by watching them.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"The team had played its best set of the whole season so far.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"The team had spent the set practicing new plays on purpose.","is_correct":false,"misconception_token":"literal-reading"}]$q$::jsonb, $q$The team had played poorly, and he was saying so gently.$q$, $q$The phrase is a euphemism: the team "had lost the first set badly," serving into the net and letting easy balls drop, and "nobody had to ask what he really meant." It was not their best set, since they lost it badly.$q$, 'draft', 'b3d29201-729c-5bf3-ad92-e68fe982d3cb')
