values
  ('97e25bf0-3078-52f5-80d5-2002e50d7c6a', null, (select id from public.skills where slug = 'read-g9-figurative-language'), null, 'medium',
   $q$Amara thinks Ngozi is "not reckless" but "just fearless." What difference between these words matters to Amara?$q$, $q$[{"text":"The two words mean the same thing, so Amara is repeating herself.","is_correct":false,"misconception_token":"ignores-connotation"},{"text":"\"Fearless\" means Ngozi plays slowly, while \"reckless\" means she plays quickly.","is_correct":false,"misconception_token":"wrong-denotation"},{"text":"\"Fearless\" suggests bravery with control, while \"reckless\" suggests careless risk.","is_correct":true},{"text":"\"Fearless\" means Ngozi never dives, while \"reckless\" means she always does.","is_correct":false,"misconception_token":"contradicts-text"}]$q$::jsonb, $q$"Fearless" suggests bravery with control, while "reckless" suggests careless risk.$q$, $q$Both words describe taking risks, but Amara adds that Ngozi "always knew exactly where the floor was," showing control, which fits the positive word "fearless." The words are not identical, since Amara says "there was a difference."$q$, 'draft', 'b3d29201-729c-5bf3-ad92-e68fe982d3cb')
