values
  ('f7f9afc0-398f-542e-b883-1ed4ea90c72d', null, (select id from public.skills where slug = 'read-g9-figurative-language'), null, 'medium',
   $q$Some of Sofia's teammates were "something closer to cocky" rather than "confident." What does the word "cocky" add?$q$, $q$[{"text":"It suggests their self-belief had become showy and disrespectful.","is_correct":true},{"text":"It suggests they were the strongest and tallest players on the court.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"It suggests they were quietly sure of themselves without showing it.","is_correct":false,"misconception_token":"ignores-connotation"},{"text":"It suggests they were nervous and unsure about winning the match.","is_correct":false,"misconception_token":"reverses-meaning"}]$q$::jsonb, $q$It suggests their self-belief had become showy and disrespectful.$q$, $q$"Cocky" carries a negative connotation that "confident" lacks, and the passage supports it with the players "pointing at the scoreboard after every kill." Quiet self-belief describes "confident," not "cocky."$q$, 'draft', 'b3d29201-729c-5bf3-ad92-e68fe982d3cb')
