  ('18bf9832-a7cc-5afd-ac3f-79ba8723a314', null, (select id from public.skills where slug = 'read-g9-figurative-language'), null, 'easy',
   $q$Dad calls the car "a classic," but Mom calls it "the dinosaur." What does Mom's word suggest?$q$, $q$[{"text":"She thinks the car is very old and out of date.","is_correct":true},{"text":"She thinks the car is the fastest one on the road.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"She thinks the car is huge and frightening to drive.","is_correct":false,"misconception_token":"literal-reading"},{"text":"She thinks the car is valuable and should be protected.","is_correct":false,"misconception_token":"ignores-connotation"}]$q$::jsonb, $q$She thinks the car is very old and out of date.$q$, $q$Both words point to the car's age, but "the dinosaur" stresses that it belongs to the past, which fits its broken air conditioner. "A classic" is the label that suggests value, and that is Dad's word, not Mom's.$q$, 'draft', 'b529d6f7-7092-5e3d-9d11-a9c17f8c195f')
