  ('7aa420cb-0fc8-5c7d-901d-c069a916eff0', null, (select id from public.skills where slug = 'read-g9-figurative-language'), null, 'medium',
   $q$Some keepers call octopuses "mischievous," while others prefer "inquisitive." How do these words differ?$q$, $q$[{"text":"\"Mischievous\" hints at playful trouble, while \"inquisitive\" stresses curiosity in a neutral way.","is_correct":true},{"text":"\"Mischievous\" describes young octopuses, while \"inquisitive\" describes old ones.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"The words mean exactly the same thing and carry the same feeling.","is_correct":false,"misconception_token":"ignores-connotation"},{"text":"\"Mischievous\" means harmful and dangerous, while \"inquisitive\" means lazy.","is_correct":false,"misconception_token":"wrong-denotation"}]$q$::jsonb, $q$"Mischievous" hints at playful trouble, while "inquisitive" stresses curiosity in a neutral way.$q$, $q$The passage says "mischievous" suggests "playful trouble rather than real harm," while "inquisitive" "sounds more scientific." So the words are close in meaning but differ in feeling, and "mischievous" is not described as harmful.$q$, 'draft', '722083c6-6b19-5207-9ec3-f9fcc6af7d55')
