  ('01886ebc-9d9d-5c6a-95ea-511edc7ef404', null, (select id from public.skills where slug = 'read-g9-literary-structure-pov'), null, 'medium',
   $q$What is the effect of the lines "and then the sky is only sky / and we are twelve people in a field"?$q$, $q$[{"text":"They reveal that the students were disappointed by the whole project.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"They mark the moment the balloon vanishes from the students' view, preparing for a shift in speaker.","is_correct":true},{"text":"They describe the field as the balloon sees it from high above.","is_correct":false,"misconception_token":"confuses-point-of-view"},{"text":"They show that the launch failed and the balloon fell back down.","is_correct":false,"misconception_token":"contradicts-text"}]$q$::jsonb, $q$They mark the moment the balloon vanishes from the students' view, preparing for a shift in speaker.$q$, $q$Once the balloon is out of sight, the students' part of the poem ends, and the next stanza takes up the balloon's view. The balloon is still rising in the final stanza, so the launch did not fail.$q$, 'draft', 'af39d5ce-0be5-5dbf-b7b4-3931e2164528')
