  ('4636740c-79f4-5b6b-b6fc-7e36f251f8a5', null, (select id from public.skills where slug = 'read-g9-literary-structure-pov'), null, 'hard',
   $q$Why might the poet have switched to the balloon's point of view for the final stanza?$q$, $q$[{"text":"To explain the science of how helium makes balloons rise","is_correct":false,"misconception_token":"misreads-purpose"},{"text":"To show that the students no longer care where the balloon goes","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"To show what the students cannot see, contrasting their big moment with how small and unaware the world below seems","is_correct":true},{"text":"To prove that the little brother was right that it would reach space","is_correct":false,"misconception_token":"outside-the-text"}]$q$::jsonb, $q$To show what the students cannot see, contrasting their big moment with how small and unaware the world below seems$q$, $q$The new speaker sees the field as "a green stamp" and a town that "never thought to look up," which the students could never witness. The poem never says whether the balloon reaches space.$q$, 'draft', 'af39d5ce-0be5-5dbf-b7b4-3931e2164528')
