  ('8c7eb712-8248-5f51-a9ee-68b5690d6e31', null, (select id from public.skills where slug = 'read-g9-literary-structure-pov'), null, 'easy',
   $q$What does the reader know that Linh's mother does not know at first?$q$, $q$[{"text":"That Mr. Halvorsen speaks fluent Vietnamese","is_correct":false,"misconception_token":"contradicts-text"},{"text":"That Linh has translated for the family for years","is_correct":false,"misconception_token":"irrelevant-detail"},{"text":"That Mr. Halvorsen thinks Linh is a strong writer","is_correct":false,"misconception_token":"too-narrow"},{"text":"That Linh left out the missing homework and the low quiz grade","is_correct":true}]$q$::jsonb, $q$That Linh left out the missing homework and the low quiz grade$q$, $q$The reader hears the teacher's full message in English and then Linh's shortened version, so only the reader knows what she skipped. Linh does tell her mother about the strong writing.$q$, 'draft', '878522c9-b6f8-5d26-9a4e-264b65f9fdcb')
