  ('4bed2c41-1b1b-53df-ac8c-bd5635bba126', null, (select id from public.skills where slug = 'read-g9-literary-structure-pov'), null, 'medium',
   $q$Why does the author include the list of things Linh has translated, such as bills, a lease and a doctor's visit?$q$, $q$[{"text":"To show that Linh plans to become a professional interpreter","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"To show how long Linh has carried this adult role, which explains the power she holds in this moment","is_correct":true},{"text":"To slow the story so that readers forget about the quiz grade","is_correct":false,"misconception_token":"misreads-purpose"},{"text":"To prove that Linh's mother does not care about her daughter's health","is_correct":false,"misconception_token":"contradicts-text"}]$q$::jsonb, $q$To show how long Linh has carried this adult role, which explains the power she holds in this moment$q$, $q$The list shows a child of immigrant parents doing serious translating since age eight, which is why Linh can control what her mother hears. Nothing mentions a career plan.$q$, 'draft', '878522c9-b6f8-5d26-9a4e-264b65f9fdcb')
