  ('05e22950-48c1-5144-8511-7eddd6065b37', null, (select id from public.skills where slug = 'read-g9-story-details-inference'), null, 'medium',
   $q$What can be inferred from the sentence "He felt his face get warm and was glad it was dark"?$q$, $q$[{"text":"Jonah was embarrassed about mistaking a plane for a meteor.","is_correct":true},{"text":"Jonah was overheated from drinking hot chocolate.","is_correct":false,"misconception_token":"literal-reading"},{"text":"Jonah was starting to feel sick from staying up late.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"Jonah was angry that Ms. Takahashi corrected him.","is_correct":false,"misconception_token":"misreads-tone"}]$q$::jsonb, $q$Jonah was embarrassed about mistaking a plane for a meteor.$q$, $q$His face grows warm right after he learns his fourth streak was a plane, and he is glad no one can see it, which points to embarrassment. Nothing in the text suggests anger, and the hot chocolate is never drunk.$q$, 'draft', 'aabf52a7-4a3e-5097-af50-5e286c452e39')
