  ('49164503-93c7-527e-875b-38947493e7ff', null, (select id from public.skills where slug = 'read-g9-story-details-inference'), null, 'hard',
   $q$When Jonah finishes, Ms. Takahashi is "awake and watching him, her hot chocolate untouched and cold." What does this most strongly suggest?$q$, $q$[{"text":"She had fallen asleep and only just woken up.","is_correct":false,"misconception_token":"ignores-evidence"},{"text":"She had not really been resting but was quietly seeing how he counted alone.","is_correct":true},{"text":"She was too cold to drink anything that night.","is_correct":false,"misconception_token":"literal-reading"},{"text":"She was disappointed in how few meteors he counted.","is_correct":false,"misconception_token":"contradicts-text"}]$q$::jsonb, $q$She had not really been resting but was quietly seeing how he counted alone.$q$, $q$She is already watching when he finishes and the drink sat untouched for a long time, which suggests she stayed alert to observe him. She later gives him credit on the report, so she was not disappointed.$q$, 'draft', 'aabf52a7-4a3e-5097-af50-5e286c452e39')
