values
  ('ce1e1835-b2d2-584d-a393-d92c8f08ead8', null, (select id from public.skills where slug = 'read-g9-theme-summary'), null, 'medium',
   $q$How does Walter Pike's letter help develop the theme?$q$, $q$[{"text":"It shows that Ida's small sacrifice, the globe, had a lasting effect on a student's life.","is_correct":true},{"text":"It reveals that Ida Marsh became famous after she stopped teaching.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"It shows that the school board had lost track of its former teachers.","is_correct":false,"misconception_token":"too-narrow"},{"text":"It explains why Amara decides she wants to study surveying in college.","is_correct":false,"misconception_token":"adds-false-detail"}]$q$::jsonb, $q$It shows that Ida's small sacrifice, the globe, had a lasting effect on a student's life.$q$, $q$Walter says he first understood maps "while spinning her globe," the globe Ida saved for three years to buy. Nothing suggests Ida became famous; her importance comes from an ordinary act.$q$, 'draft', '113f0458-6fc3-5ad7-bddb-576dc8559945')
