  ('22bfc5ab-c541-5837-8228-5587b20430c7', null, (select id from public.skills where slug = 'read-g9-theme-summary'), null, 'hard',
   $q$How does the speaker's view of the father's work change between the fifth and sixth stanzas?$q$, $q$[{"text":"It changes from seeing his unnoticed work as sad to seeing it as quietly meaningful.","is_correct":true},{"text":"It changes from interest in bread to interest in the customers who buy it.","is_correct":false,"misconception_token":"misses-main-idea"},{"text":"It changes from admiration for his skill to resentment of his long hours.","is_correct":false,"misconception_token":"reverses-change"},{"text":"It changes from worry about his health to relief that he is finally resting.","is_correct":false,"misconception_token":"unsupported-inference"}]$q$::jsonb, $q$It changes from seeing his unnoticed work as sad to seeing it as quietly meaningful.$q$, $q$Stanza five begins "I used to think that this was sad," and stanza six answers "But now I think he likes it so," because the town is fed. The resentment choice reverses the actual direction of the change.$q$, 'draft', 'e1083313-f281-5516-b4ab-a092af8eabbf')
