  ('dbea03a9-0760-5018-9798-b25bf00f919d', null, (select id from public.skills where slug = 'read-g9-theme-summary'), null, 'easy',
   $q$Which statement best expresses a central theme of the passage?$q$, $q$[{"text":"Students should finish all their homework before leaving home.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"City buses should always leave each stop exactly on schedule.","is_correct":false,"misconception_token":"opposite-of-theme"},{"text":"Substitute workers are usually rude and careless with the public.","is_correct":false,"misconception_token":"overgeneralization"},{"text":"Small, patient acts of care can turn a group of strangers into a community.","is_correct":true}]$q$::jsonb, $q$Small, patient acts of care can turn a group of strangers into a community.$q$, $q$Mr. Ibarra's habits make the bus friendly, and when they disappear the riders grow distant. The substitute is described as "polite," so calling substitutes rude is an overgeneralization the text does not support.$q$, 'draft', 'c6ed9f45-fcff-52c9-83c0-ef74c1de5407')
